import zipfile
import os
import shutil
import re

output_path = '/root/safety_audit_brief_final.hwpx'
verify_dir = '/tmp/hwpx_verify'

# Clean and extract
if os.path.exists(verify_dir):
    shutil.rmtree(verify_dir)
os.makedirs(verify_dir)

with zipfile.ZipFile(output_path, 'r') as zipf:
    zipf.extractall(verify_dir)

print("=== VALIDATION RESULTS ===\n")

# 1. Check no placeholders remain
print("1. Checking for remaining placeholders:")
placeholders_found = False
for root, dirs, files in os.walk(verify_dir):
    for file in files:
        if file.endswith('.xml'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                if '{{' in content:
                    placeholders_found = True
                    print(f"   FAIL: Found placeholder in {file}")
                    for line in content.split('\n'):
                        if '{{' in line:
                            print(f"      Line: {line[:150]}")
if not placeholders_found:
    print("   PASS: No placeholders found")

# 2. Verify date format YYYY.MM.DD (no YYYY-MM-DD remaining)
print("\n2. Checking date format (should be YYYY.MM.DD):")
dates_found = False
for root, dirs, files in os.walk(verify_dir):
    for file in files:
        if file.endswith('.xml'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                matches = re.findall(r'\d{4}-\d{2}-\d{2}', content)
                if matches:
                    dates_found = True
                    print(f"   FAIL: Found YYYY-MM-DD format in {file}: {matches}")
if not dates_found:
    print("   PASS: All dates are in YYYY.MM.DD format")

# 3. Verify severity notes are present
print("\n3. Checking severity notes (즉시조치/계획보완/모니터링):")
severity_found = False
for root, dirs, files in os.walk(verify_dir):
    for file in files:
        if file.endswith('.xml'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                if '즉시조치' in content or '계획보완' in content or '모니터링' in content:
                    severity_found = True
                    print(f"   PASS: Found severity note in {file}")
                    # Show the line
                    for line in content.split('\n'):
                        if '즉시조치' in line or '계획보완' in line or '모니터링' in line:
                            print(f"      {line.strip()[:200]}")
if not severity_found:
    print("   FAIL: No severity notes found")

# 4. Verify layout cache elements removed from modified paragraphs
print("\n4. Checking layout cache elements (linesegarray) removal:")
layout_cache_found = False
for root, dirs, files in os.walk(verify_dir):
    for file in files:
        if file.endswith('.xml'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                if 'linesegarray' in content.lower():
                    layout_cache_found = True
                    print(f"   WARNING: Found linesegarray in {file}")
if not layout_cache_found:
    print("   PASS: No linesegarray elements found")

# 5. Verify section titles and row labels are preserved
print("\n5. Checking section titles and row labels:")
for root, dirs, files in os.walk(verify_dir):
    for file in files:
        if file.endswith('.xml'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()

                # Check for section titles
                if '창고 안전 점검 브리프' in content:
                    print("   PASS: Section title '창고 안전 점검 브리프' preserved")
                if '즉시 조치 항목' in content:
                    print("   PASS: Section title '즉시 조치 항목' preserved")

                # Check for row labels
                if '현장명' in content:
                    print("   PASS: Row label '현장명' preserved")
                if '주관 점검자' in content:
                    print("   PASS: Row label '주관 점검자' preserved")
                if '점검일' in content:
                    print("   PASS: Row label '점검일' preserved")
                if '위험 등급' in content:
                    print("   PASS: Row label '위험 등급' preserved")

# 6. Show final content sample
print("\n6. Sample of final content from section0.xml:")
section0_path = os.path.join(verify_dir, 'Contents', 'section0.xml')
if os.path.exists(section0_path):
    with open(section0_path, 'r', encoding='utf-8') as f:
        content = f.read()
        # Extract readable text
        import xml.etree.ElementTree as ET
        root = ET.fromstring(content)
        for elem in root.iter():
            if elem.tag.endswith('}t') and elem.text:
                if 'SAF' in elem.text or '점검' in elem.text or 'High' in elem.text or '2026' in elem.text:
                    print(f"   {elem.text}")

print("\n=== VALIDATION COMPLETE ===")
